<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rentabilité des stations · Thiebapower</title><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/station-experience.css?v=1"></head><body class="admin-body"><?php $adminPageTitle='Rentabilité des stations';$adminPageSubtitle='Revenus et coûts depuis le début du suivi';require __DIR__.'/partials/admin_shell_start.php';$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$money=static fn($v)=>number_format((int)$v,0,',',' ').' FCFA';$types=['payment_fee'=>'Frais de paiement','maintenance'=>'Maintenance','venue'=>'Frais du lieu','other'=>'Autre']; ?>
<main class="management-main"><section class="management-card"><p>Revenus = tarifs des locations avec paiement réel vérifié et sortie confirmée + retenues clôturées. Résultat suivi = revenus − coûts saisis. Les cautions remboursables et les simulations sont exclues. Le résultat reste indicatif tant que tous les coûts ne sont pas renseignés.</p><p>Les coûts servent ici à analyser la rentabilité. Ils ne créent pas de mouvement de caisse : enregistrez le décaissement dans la caisse si nécessaire.</p><div class="management-table-wrap"><table><thead><tr><th>Station</th><th>Locations</th><th>Revenus</th><th>Retenues</th><th>Coûts</th><th>Résultat suivi</th><th>Investissement</th><th>Reste à récupérer</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="/admin/stations/detail?imei=<?= rawurlencode($r['imei']) ?>"><?= $h($r['label']?:$r['imei']) ?></a></td><td><?= (int)$r['rentals'] ?></td><td><?= $money($r['revenue']) ?></td><td><?= $money($r['deductions']) ?></td><td><?= $money($r['costs']) ?></td><td><?= $money($r['net']) ?></td><td><?= $money($r['investment']) ?></td><td><?= $r['investment']?$money($r['remaining']):'Investissement à renseigner' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if(App\Services\Auth::can('finance.manage')): ?><section class="management-card"><h2>Investissement initial</h2><form method="post" action="/admin/stations/investment"><input type="hidden" name="csrf" value="<?= $h($_SESSION['csrf']) ?>"><label>Station<select name="imei"><?php foreach($rows as $r): ?><option value="<?= $h($r['imei']) ?>"><?= $h($r['label']?:$r['imei']) ?></option><?php endforeach; ?></select></label><label>Investissement total (FCFA)<input name="investment" type="number" min="0" max="1000000000" required></label><button class="admin-button">Enregistrer l’investissement</button></form></section>
<section class="management-card"><h2>Enregistrer un coût</h2><form method="post" action="/admin/stations/cost"><input type="hidden" name="request_token" value="<?= bin2hex(random_bytes(16)) ?>"><input type="hidden" name="csrf" value="<?= $h($_SESSION['csrf']) ?>"><div class="management-grid"><label>Station<select name="imei"><?php foreach($rows as $r): ?><option value="<?= $h($r['imei']) ?>"><?= $h($r['label']?:$r['imei']) ?></option><?php endforeach; ?></select></label><label>Catégorie<select name="category"><?php foreach($types as $key=>$label): ?><option value="<?= $key ?>"><?= $h($label) ?></option><?php endforeach; ?></select></label><label>Montant (FCFA)<input name="amount" type="number" min="1" max="1000000000" required></label><label>Date<input name="occurred_on" type="date" value="<?= gmdate('Y-m-d') ?>" required></label></div><label>Description<input name="description" maxlength="250" required></label><button class="admin-button">Enregistrer ce coût</button></form></section><?php endif; ?>
<section class="management-card"><h2>Derniers coûts enregistrés</h2><div class="management-table-wrap"><table><thead><tr><th>Date</th><th>Station</th><th>Catégorie</th><th>Description</th><th>Montant</th></tr></thead><tbody><?php foreach($costs as $c): ?><tr><td><?= $h($c['occurred_on']) ?></td><td><?= $h($c['label']?:$c['station_imei']) ?></td><td><?= $h($types[$c['category']]) ?></td><td><?= $h($c['description']) ?></td><td><?= $money($c['amount']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><?php require __DIR__.'/partials/admin_shell_end.php'; ?></body></html>
